/* Token Radar's plain theme. The five palette values, two radii and two families are the whole style;
   everything else is spacing, a hairline and a type step. */
:root {
  --canvas: #f2f5f3;
  --surface: #ffffff;
  --ink: #16211c;
  --muted: #5f6f67;
  --border: #d8e2dc;
  --accent: #0f7a5a;
  --negative: #b23b2e;
  --radius-control: 8px;
  --radius-panel: 14px;
  --font-body: system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-num: ui-monospace, "SF Mono", Menlo, monospace;
  --step-1: 4px;
  --step-2: 8px;
  --step-3: 12px;
  --step-4: 16px;
  --step-5: 24px;
  --step-6: 32px;
  --step-7: 48px;
}

* { box-sizing: border-box; }
html { color-scheme: light; }
body {
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font: 400 15px/1.5 var(--font-body);
  text-wrap: pretty;
}
h1, h2, h3 { margin: 0; letter-spacing: -0.02em; text-wrap: balance; }
h1 { font-size: 30px; line-height: 1.15; font-weight: 600; }
h2 { font-size: 20px; line-height: 1.2; font-weight: 600; }
h3 { font-size: 16px; line-height: 1.25; font-weight: 600; }
p { margin: 0; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
a { color: var(--accent); }
.skip {
  position: absolute; left: -9999px; top: 0; padding: var(--step-2) var(--step-4);
  background: var(--surface); border: 1px solid var(--border); z-index: 20;
}
.skip:focus { left: var(--step-4); top: var(--step-4); }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.shell { max-width: 1320px; margin: 0 auto; padding: var(--step-5) var(--step-6) var(--step-7); }
.top {
  display: flex; align-items: flex-start; justify-content: space-between; gap: var(--step-5);
  padding-bottom: var(--step-4); border-bottom: 1px solid var(--border);
}
.brand { display: flex; align-items: center; gap: var(--step-3); }
.mark { width: 12px; height: 12px; border-radius: 50%; background: var(--accent); flex: none; }
.brand-name { font-family: var(--font-num); font-size: 13px; letter-spacing: 0.02em; color: var(--muted); }
.top-meta { display: flex; flex-wrap: wrap; gap: var(--step-3); justify-content: flex-end; color: var(--muted); font-size: 13px; }
.top-meta span { white-space: nowrap; }
.lede { display: grid; grid-template-columns: minmax(0, 1.35fr) minmax(280px, 0.65fr); gap: var(--step-6); padding: var(--step-6) 0 var(--step-5); }
.lede p { color: var(--muted); max-width: 62ch; margin-top: var(--step-2); }
.facts { display: grid; gap: var(--step-2); align-content: start; border-left: 1px solid var(--border); padding-left: var(--step-5); }
.fact { display: flex; align-items: baseline; justify-content: space-between; gap: var(--step-3); }
.fact b { font-family: var(--font-num); font-size: 15px; font-weight: 500; }
.fact span { color: var(--muted); font-size: 13px; }

.controls { display: flex; flex-wrap: wrap; align-items: end; gap: var(--step-3); padding: var(--step-4) 0; border-top: 1px solid var(--border); }
.field { display: grid; gap: var(--step-1); }
.field label { color: var(--muted); font-size: 12px; }
.field input, .field select {
  min-height: 36px; padding: 0 var(--step-3); border: 1px solid var(--border); border-radius: var(--radius-control);
  background: var(--surface); min-width: 180px;
}
.field input { min-width: 280px; }
.tabs { display: flex; gap: var(--step-1); padding: 3px; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); }
.tabs button { min-height: 30px; padding: 0 var(--step-3); border: 0; border-radius: 6px; background: transparent; color: var(--muted); }
.tabs button[aria-pressed="true"] { background: var(--ink); color: var(--surface); }
.count { margin-left: auto; color: var(--muted); font-size: 13px; align-self: center; }

.panel { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-panel); overflow: hidden; }
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
th, td { padding: var(--step-3) var(--step-3); border-bottom: 1px solid var(--border); text-align: left; vertical-align: middle; }
th { color: var(--muted); font-size: 12px; font-weight: 500; white-space: nowrap; }
th button { display: inline-flex; align-items: center; gap: var(--step-1); border: 0; background: none; padding: 0; color: inherit; font: inherit; }
th button:hover { color: var(--ink); }
tbody tr { cursor: pointer; }
tbody tr:hover { background: var(--surface); }
tbody tr[data-selected="true"] { background: color-mix(in srgb, var(--accent) 8%, var(--surface)); }
.num { font-family: var(--font-num); font-variant-numeric: tabular-nums; white-space: nowrap; }
.name { display: grid; gap: 2px; }
.name b { font-weight: 600; }
.sub { color: var(--muted); font-size: 12px; }
.pos { color: var(--accent); }
.neg { color: var(--negative); }
.bar { width: 120px; height: 6px; border-radius: 3px; background: color-mix(in srgb, var(--border) 60%, var(--surface)); overflow: hidden; }
.bar i { display: block; height: 100%; background: var(--accent); }
.implied { display: flex; align-items: center; gap: var(--step-2); }
.status { display: inline-flex; align-items: center; gap: 6px; color: var(--muted); font-size: 12px; white-space: nowrap; }
.status::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--accent); }

.model { margin-top: var(--step-4); padding: var(--step-5); display: grid; gap: var(--step-3); }
.formula { font-family: var(--font-num); font-size: 13px; line-height: 1.7; color: var(--muted); overflow-wrap: anywhere; }
.badge { display: inline-block; margin-top: 2px; padding: 1px 6px; border: 1px solid var(--accent); border-radius: 999px; color: var(--accent); font-size: 11px; font-weight: 600; letter-spacing: 0.02em; }
/* The backtest and the launch score, inside the model panel: a heading and a short paragraph each. */
.validation { display: grid; gap: var(--step-2); margin-top: var(--step-2); }
.validation h3 { font-size: 14px; }
.empty { padding: var(--step-7) var(--step-5); text-align: center; display: grid; gap: var(--step-3); justify-items: center; }
.empty p { color: var(--muted); }
.button { min-height: 36px; padding: 0 var(--step-4); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); }
.button.primary { background: var(--accent); border-color: var(--accent); color: var(--surface); }

.detail {
  position: fixed; top: 0; right: 0; bottom: 0; width: min(520px, 92vw); z-index: 10;
  background: var(--surface); border-left: 1px solid var(--border); padding: var(--step-5);
  overflow-y: auto; transform: translateX(0); transition: transform 200ms cubic-bezier(0, 0, 0.2, 1);
}
.detail[hidden] { display: none; }
.detail { margin: 0 0 0 auto; max-height: 100%; }
.detail::backdrop { background: rgba(22, 33, 28, 0.28); }
.detail-head { display: flex; align-items: start; justify-content: space-between; gap: var(--step-4); }
.detail-head > div { min-width: 0; }
.detail-head .sub { overflow-wrap: anywhere; }
.close { flex: none; min-width: 32px; min-height: 32px; padding: 0 var(--step-2); white-space: nowrap; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); }
.detail h2 { margin-top: var(--step-1); }
.detail .sub { margin-top: var(--step-1); }
.detail-section { margin-top: var(--step-5); padding-top: var(--step-4); border-top: 1px solid var(--border); }
.detail-section h3 { margin-bottom: var(--step-2); }
.equation { display: grid; gap: var(--step-2); font-family: var(--font-num); font-size: 13px; }
.equation div { display: flex; justify-content: space-between; gap: var(--step-3); }
.equation span { color: var(--muted); }
.steps { margin: 0; padding-left: var(--step-5); display: grid; gap: var(--step-3); }
.steps li { padding-left: var(--step-1); }
.steps b { display: block; font-weight: 500; }
.cost { color: var(--muted); font-size: 12px; font-family: var(--font-num); }

/* The comparison: two protocols side by side, with the stronger figure in each row set bold. */
.compare { margin-top: var(--step-4); padding: var(--step-5); display: grid; gap: var(--step-3); }
.compare-head { display: flex; align-items: center; justify-content: space-between; gap: var(--step-4); }
.compare table { font-size: 13px; }
.compare th[scope="row"] { color: var(--muted); font-weight: 500; white-space: nowrap; }
.compare td.win { font-weight: 700; color: var(--accent); }
.compare .sub { margin-top: 0; }
/* The per-row compare toggle: quiet until a protocol is picked, then it reads as picked. */
.compare-toggle {
  display: inline-block; margin-left: var(--step-2); padding: 2px var(--step-2);
  border: 1px solid var(--border); border-radius: 999px; background: transparent;
  color: var(--muted); font-size: 11px; font-weight: 600; white-space: nowrap;
}
.compare-toggle[aria-pressed="true"] { background: var(--accent); border-color: var(--accent); color: var(--surface); }
.compare-toggle:hover { border-color: var(--accent); color: var(--accent); }
.compare-toggle[aria-pressed="true"]:hover { color: var(--surface); }
/* The category leaders: one card per category, each a button that opens the protocol. */
.leaders { margin-top: var(--step-4); padding: var(--step-5); display: grid; gap: var(--step-3); }
.leader-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: var(--step-3); }
.leader {
  display: grid; gap: 2px; text-align: left; padding: var(--step-3) var(--step-4);
  border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface);
}
.leader:hover { border-color: var(--accent); }
.leader-cat { color: var(--muted); font-size: 11px; font-weight: 600; letter-spacing: 0.04em; text-transform: uppercase; }
.leader b { font-weight: 600; font-size: 14px; }
.leader-value { font-family: var(--font-num); font-size: 13px; color: var(--accent); }
.leader .sub { margin-top: 0; }

/* The fastest movers: one row per protocol, growth first so momentum reads at a glance. */
.movers { margin-top: var(--step-4); padding: var(--step-5); display: grid; gap: var(--step-3); }
.mover-list { display: grid; gap: var(--step-2); }
.mover {
  display: flex; align-items: baseline; gap: var(--step-3); text-align: left;
  padding: var(--step-2) var(--step-3); border: 1px solid var(--border);
  border-radius: var(--radius-control); background: var(--surface);
}
.mover:hover { border-color: var(--accent); }
.mover-growth { font-family: var(--font-num); font-weight: 700; color: var(--accent); min-width: 72px; }
.mover b { font-weight: 600; }
.mover .sub { margin-left: auto; text-align: right; }
/* How to read the board: a numbered guide, each step one sentence of action and one of reason. */
.howto { margin-top: var(--step-4); padding: var(--step-5); display: grid; gap: var(--step-3); }
.howto-list { margin: 0; padding-left: var(--step-5); display: grid; gap: var(--step-2); }
.howto-list li { padding-left: var(--step-1); color: var(--muted); }
.howto-list b { color: var(--ink); font-weight: 600; }
/* The methodology footer: the radar's method in plain words, at the bottom of the page. */
.method { margin-top: var(--step-4); padding: var(--step-5); border-top: 1px solid var(--border); display: grid; gap: var(--step-2); }
.method h2 { font-size: 16px; }
.method p { color: var(--muted); font-size: 13px; max-width: 78ch; }

@media (max-width: 900px) {
  .shell { padding: var(--step-4); }
  .lede { grid-template-columns: 1fr; gap: var(--step-4); }
  .facts { border-left: 0; border-top: 1px solid var(--border); padding-left: 0; padding-top: var(--step-4); }
  .field input { min-width: 0; width: 100%; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; }
}
